    p=subprocess.run(argv,cwd=copy,capture_output=True,text=True)
    evidence.append({'test':'original-postbuild','argv':argv,'cwd':str(copy),'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}); return p.returncode
def isolated_delete(path,expected):
    path=path.resolve(); assert path.is_relative_to(copy.resolve()); assert path.is_file() and sha(path)==expected
    assert not subprocess.run(['git','-c','safe.directory=C:/dev/GEngine-build','ls-files','--',path.relative_to(root).as_posix()],capture_output=True,text=True,check=True).stdout
    path.unlink()
for config in ['Debug','Release']:
    for app in apps: assert original(config,app)==0
assert len(check(copy/'bin'))==8
missing=copy/'bin/Debug/RayTracing/tbb12.dll'; isolated_delete(missing,DLL_SHA)
assert original('Debug','RayTracing')==0
try: check(copy/'bin')
except AssertionError as error: evidence.append({'test':'new-safeguard-missing-tbb','result':'PASS rejected missing runtime','message':str(error)})
else: raise AssertionError('Missing TBB was accepted')
stage(copy/'bin'); assert sha(missing)==DLL_SHA
isolated_delete(missing,DLL_SHA); missing.write_bytes(b'wrong-runtime-content')
wrong=sha(missing)
try: stage(copy/'bin')
except AssertionError as error: evidence.append({'test':'refuse-mismatched-preexisting-output','result':'PASS','message':str(error)})
else: raise AssertionError('Corrupt output was overwritten')
assert sha(missing)==wrong; isolated_delete(missing,wrong); stage(copy/'bin')
try: supply(root/'bin/Debug/RayTracing/SDL2.dll',missing,copy/'bin')
except AssertionError as error: evidence.append({'test':'refuse-wrong-source-runtime','result':'PASS','message':str(error)})
else: raise AssertionError('Wrong source accepted')
tracked=root/'bin/Debug/RayTracing/SDL2.dll'
try: supply(SOURCE,tracked,root/'bin')
except AssertionError as error: evidence.append({'test':'refuse-protected-tracked-destination','result':'PASS','message':str(error)})
else: raise AssertionError('Protected target accepted')
sdl=copy/'bin/Debug/RayTracing/SDL2.dll'; expected=sha(sdl); isolated_delete(sdl,expected)
assert original('Debug','RayTracing')!=0
shutil.copy2(tracked,sdl); assert sha(sdl)==expected
before=sha(missing); again=stage(copy/'bin'); assert sha(missing)==before
assert all(x['action']=='verified-existing; no write' for x in again)
assert len(check(copy/'bin'))==8
assert all(sha(path)==h for path,h in protected.items())
result={'result':'PASS','copy_root':str(copy),'records':evidence,'idempotence':again,'original_bytes_preserved':protected,'original_safeguard_gap':'Original safeguard passes with missing TBB; the new hash-verified supplement rejects it. Original SDL missing-file rejection remains effective.'}
(root/'docs/build/evidence/phase-00/revision-01/safeguard-results.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,indent=2))

